<section class="panel"><h2><?= $student?'Student information':'Start with the student' ?></h2><p class="muted">Configure academic years, classes and student types in Academic setup before registering a student.</p><?php startForm('student.save',$student?['id'=>$student['id']]:[]); foreach(['admission_number'=>'Admission number','first_name'=>'First name','middle_name'=>'Middle name','last_name'=>'Last name'] as $key=>$label) field($key,$label,'text',$student[$key]??'',$key!=='middle_name'); selectField('gender','Gender',['Female','Male','Other'],$student['gender']??''); field('date_of_birth','Date of birth','date',$student['date_of_birth']??''); field('admission_date','Admission date','date',$student['admission_date']??date('Y-m-d')); selectField('status','Status',['Active','Graduated','Transferred','Withdrawn','Suspended'],$student['status']??'Active'); foreach(['phone'=>'Student phone','email'=>'Student email','guardian_name'=>'Guardian name','guardian_phone'=>'Guardian phone','address'=>'Address'] as $key=>$label) field($key,$label,$key==='email'?'email':'text',$student[$key]??'',false); if(!$student): ?><h3 class="full">Initial academic enrollment</h3><?php enrollmentFields(); endif; endForm($student?'Save changes':'Register student'); ?></section>
